"""Self-contained, offline HTML dashboard for PEG-TRIAGE reports."""

import json


def render_dashboard(report: dict) -> str:
    """Render a portable report page with no network requests or dependencies."""
    payload = json.dumps(report, ensure_ascii=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    payload = payload.replace("</", "<\\/")
    return """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="dark"><title>PEG-TRIAGE | Forensic analysis</title>
<style>
:root{--bg:#09131b;--panel:#101f2a;--panel2:#142632;--line:#253944;--text:#edf4f3;--muted:#9bafb2;--mint:#83e0c0;--amber:#f3c979;--red:#ff9089;--blue:#8ab8ff;--mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;--sans:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 78% -10%,#16363c 0,transparent 36%),var(--bg);color:var(--text);font:15px/1.55 var(--sans)}a{color:var(--mint)}.wrap{max-width:1220px;margin:auto;padding:38px 30px 64px}.top{display:flex;align-items:center;justify-content:space-between;gap:18px;border-bottom:1px solid var(--line);padding-bottom:24px}.brand{display:flex;gap:14px;align-items:center}.mark{width:44px;height:44px;border:1px solid #368f79;border-radius:14px;display:grid;place-items:center;background:#10342f;color:var(--mint);font-weight:800;letter-spacing:-1px}.eyebrow,.caps{font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);font-weight:700}.title{font-size:23px;line-height:1.2;margin:2px 0;font-weight:720}.meta{color:var(--muted);font-size:13px}.badge{border:1px solid var(--line);border-radius:999px;padding:7px 12px;color:var(--mint);font-size:12px;white-space:nowrap}.intro{margin:30px 0 21px;display:flex;justify-content:space-between;align-items:end;gap:20px}.intro h1{font-size:29px;letter-spacing:-.04em;margin:0}.intro p{margin:5px 0 0;color:var(--muted)}.stamp{font:12px var(--mono);color:var(--muted);text-align:right}.grid{display:grid;grid-template-columns:1.25fr repeat(3,1fr);gap:13px}.card{background:linear-gradient(145deg,#142630,#0f1c26);border:1px solid var(--line);border-radius:16px;padding:19px;min-width:0}.verdict{position:relative;overflow:hidden}.verdict:after{content:"";position:absolute;width:180px;height:180px;border-radius:50%;right:-65px;top:-90px;background:var(--glow);filter:blur(1px);opacity:.12}.verdict.high{--glow:var(--red)}.verdict.medium{--glow:var(--amber)}.verdict.low{--glow:var(--mint)}.metric{font-size:39px;font-weight:760;letter-spacing:-.06em;margin-top:8px}.metric-label{font-size:13px;color:var(--muted)}.verdict-word{font-size:24px;font-weight:750;color:var(--glow);margin-top:3px}.panel-title{font-size:14px;font-weight:700;margin:0 0 13px}.small{font-size:12px;color:var(--muted)}.section{margin-top:20px}.section-head{display:flex;align-items:end;justify-content:space-between;gap:15px;margin:31px 0 12px}.section-head h2{font-size:17px;margin:0;letter-spacing:-.02em}.score-layout{display:grid;grid-template-columns:1.2fr .8fr;gap:13px}.barrow{display:grid;grid-template-columns:132px 1fr 42px;gap:12px;align-items:center;margin:13px 0;font-size:13px}.barlabel{color:#c5d3d2}.track{height:8px;background:#243641;border-radius:99px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#3aa88d,var(--mint));border-radius:99px}.barval{text-align:right;color:var(--muted);font:12px var(--mono)}.cluster{display:flex;align-items:center;gap:13px;padding:17px;background:#0d1a23;border:1px solid var(--line);border-radius:12px}.cluster-icon{width:39px;height:39px;border-radius:12px;background:#1d3540;display:grid;place-items:center;color:var(--blue);font-size:19px}.cluster strong{display:block}.cluster.yes .cluster-icon{background:#20372f;color:var(--mint)}.cluster.no .cluster-icon{color:var(--amber)}.tablebox{overflow:hidden;border:1px solid var(--line);border-radius:14px;background:#0e1a23}.tools{padding:12px;display:flex;justify-content:space-between;gap:12px;align-items:center;border-bottom:1px solid var(--line)}input{background:#0a151d;color:var(--text);border:1px solid var(--line);padding:9px 12px;border-radius:9px;min-width:230px;font:13px var(--sans);outline:none}input:focus{border-color:#4f9c89}.button{color:var(--text);background:#192b36;border:1px solid var(--line);border-radius:9px;padding:9px 12px;font:12px var(--sans);cursor:pointer;text-decoration:none}.button:hover{border-color:#4f9c89}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;min-width:790px;text-align:left}th{font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);font-weight:700;background:#12232d}th,td{padding:12px 14px;border-bottom:1px solid #1d303a;vertical-align:top}td{font-size:12px;color:#cfdbda}td code,.hash code{font:11px var(--mono);overflow-wrap:anywhere;color:#b9d5d0}.tag{display:inline-flex;padding:3px 8px;border:1px solid #315045;background:#142e29;color:var(--mint);border-radius:99px;font-size:11px}.points{font:12px var(--mono);color:var(--amber)}.empty{padding:24px;text-align:center;color:var(--muted)}.hashes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.hash{padding:13px 14px;background:#101f29;border:1px solid var(--line);border-radius:11px;min-width:0}.hash-name{font-size:12px;margin-bottom:7px;color:#cbd8d7}.hash-meta{color:var(--muted);font-size:11px}.notice{margin-top:22px;padding:16px 18px;border:1px solid #5e5136;background:#282316;border-radius:13px;color:#dfd1ac;font-size:12px}.notice strong{color:#f2dfa9}.foot{display:flex;justify-content:space-between;gap:10px;margin-top:24px;padding-top:16px;border-top:1px solid var(--line);color:var(--muted);font-size:11px}.mono{font-family:var(--mono)}
@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.score-layout{grid-template-columns:1fr}.intro{align-items:start;flex-direction:column}.stamp{text-align:left}}@media(max-width:560px){.wrap{padding:23px 15px 42px}.top{align-items:start}.badge{display:none}.grid{grid-template-columns:1fr 1fr}.verdict{grid-column:span 2}.hashes{grid-template-columns:1fr}.barrow{grid-template-columns:100px 1fr 34px}.tools{align-items:stretch;flex-direction:column}input{min-width:0;width:100%}.title{font-size:18px}.intro h1{font-size:25px}}
@media print{body{background:white;color:#17232b}.wrap{max-width:none;padding:10px}.card,.tablebox,.hash{background:white;color:#17232b;border-color:#ccd5d8}.meta,.small,.stamp,.foot,.hash-meta{color:#53656b}.notice{background:#fff8e8;color:#333}.tools input,.tools button{display:none}table{min-width:0}th{background:#edf2f2;color:#344}td{color:#17232b}}
</style></head><body><main class="wrap">
<header class="top"><div class="brand"><div class="mark">PT</div><div><div class="eyebrow">Mobile forensics · Case analysis</div><div class="title">PEG-TRIAGE <span class="meta">/ analysis report</span></div></div></div><div class="badge">OFFLINE REPORT · SELF-CONTAINED</div></header>
<section class="intro"><div><h1>Evidence correlation</h1><p>Auditable findings across acquired artifact sources.</p></div><div class="stamp" id="generated"></div></section>
<section class="grid"><article class="card verdict" id="verdict-card"><div class="caps">Triage assessment</div><div class="verdict-word" id="verdict"></div><div class="metric" id="score"></div><div class="metric-label">weighted points · proposed model</div></article><article class="card"><div class="caps">Scored findings</div><div class="metric" id="finding-count"></div><div class="metric-label">items with non-zero weight</div></article><article class="card"><div class="caps">Evidence files</div><div class="metric" id="file-count"></div><div class="metric-label">hashed input artifacts</div></article><article class="card"><div class="caps">Time correlation</div><div class="metric" id="cluster-status"></div><div class="metric-label" id="cluster-window"></div></article></section>
<section class="section"><div class="section-head"><h2>How the score was formed</h2><span class="small">Transparent point contributions</span></div><div class="score-layout"><article class="card"><div class="panel-title">Points by signal type</div><div id="bars"></div></article><article class="card"><div class="panel-title">Correlation rule</div><div class="cluster" id="cluster-card"><div class="cluster-icon">↗</div><div><strong id="cluster-title"></strong><span class="small" id="cluster-copy"></span></div></div><p class="small" style="margin:14px 2px 0">Two different signal types within the configured time window multiply the summed score by 1.5.</p></article></div></section>
<section class="section"><div class="section-head"><h2>Evidence timeline</h2><span class="small" id="timeline-count"></span></div><div class="tablebox"><div class="tools"><input id="filter" type="search" placeholder="Filter artifact, signal, or value…" aria-label="Filter timeline"><button class="button" id="download">Download machine-readable JSON</button></div><div class="table-scroll"><table><thead><tr><th>Timestamp (UTC)</th><th>Signal</th><th>Observed value</th><th>Points</th><th>Source artifact</th><th>Analyst-readable reason</th></tr></thead><tbody id="events"></tbody></table><div class="empty" id="empty" hidden>No timeline entries match this filter.</div></div></div></section>
<section class="section"><div class="section-head"><h2>Input integrity</h2><span class="small">SHA-256 fingerprints recorded at analysis time</span></div><div class="hashes" id="hashes"></div></section>
<aside class="notice"><strong>Interpret with care.</strong> PEG-TRIAGE is an educational triage aid, not a validated Pegasus detector or forensic conclusion. A Low score means no corroborated indicators appeared in the supplied artifacts; it does not establish that a device is clean. Validate findings with a qualified examiner and independent methods.</aside>
<footer class="foot"><span>PEG-TRIAGE · v<span id="version"></span> · Generated <span id="footer-date"></span></span><span>Local file · No external scripts, fonts, or network requests</span></footer>
</main><script id="report-data" type="application/json">__REPORT_DATA__</script><script>
const D=JSON.parse(document.getElementById('report-data').textContent);const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>{if(!s)return'Unknown';const d=new Date(s);return Number.isNaN(+d)?esc(s):d.toISOString().replace('T',' ').replace('Z',' UTC')};
$('generated').textContent='GENERATED '+date(D.generated_utc);$('footer-date').textContent=date(D.generated_utc);$('version').textContent=D.version;$('verdict').textContent=D.verdict+' confidence';$('score').textContent=D.score;$('finding-count').textContent=D.evidence_log.length;$('file-count').textContent=D.input_hashes.length;$('cluster-status').textContent=D.temporal_cluster?'Yes':'No';$('cluster-window').textContent=D.cluster_window_seconds+' second window';
const vc=$('verdict-card');vc.classList.add(String(D.verdict||'low').toLowerCase());$('cluster-card').classList.add(D.temporal_cluster?'yes':'no');$('cluster-title').textContent=D.temporal_cluster?'Temporal cluster detected':'No temporal cluster';$('cluster-copy').textContent=D.temporal_cluster?' Different signal types co-occur inside the configured window.':' No pair of different signal types co-occurred inside the window.';$('cluster-status').style.color=D.temporal_cluster?'var(--mint)':'var(--amber)';
const labels={process:'Known process',domain:'IOC domain',shutdown:'Shutdown log',unknown_network:'Unknown network',profile:'Profile context',crash:'Crash context'};const totals={};for(const e of D.evidence_log)totals[e.signal_type]=(totals[e.signal_type]||0)+Number(e.weight||0);const max=Math.max(1,...Object.values(totals));$('bars').innerHTML=Object.entries(labels).map(([k,l])=>`<div class="barrow"><div class="barlabel">${l}</div><div class="track"><div class="fill" style="width:${Math.min(100,(totals[k]||0)/max*100)}%"></div></div><div class="barval">${totals[k]||0}</div></div>`).join('');
const all=D.timeline||[];$('timeline-count').textContent=all.length+' normalized event'+(all.length===1?'':'s');function draw(){const q=$('filter').value.toLowerCase().trim();const rows=all.filter(e=>[e.timestamp,e.signal_type,e.value,e.source,e.reason,e.detail].join(' ').toLowerCase().includes(q));$('events').innerHTML=rows.map(e=>`<tr><td class="mono">${esc(date(e.timestamp))}</td><td><span class="tag">${esc(e.signal_type)}</span></td><td><code>${esc(e.value)}</code></td><td class="points">${Number(e.weight||0)?'+'+e.weight:'—'}</td><td><code>${esc(e.source)}</code></td><td>${esc(e.reason||'Context only')}</td></tr>`).join('');$('empty').hidden=rows.length>0}draw();$('filter').addEventListener('input',draw);
for(const h of D.input_hashes){const item=document.createElement('div');item.className='hash';item.innerHTML=`<div class="hash-name"></div><div><code></code></div><div class="hash-meta"></div>`;item.querySelector('.hash-name').textContent=h.path;item.querySelector('code').textContent=h.sha256;item.querySelector('.hash-meta').textContent=Number(h.bytes).toLocaleString()+' bytes · SHA-256';$('hashes').append(item)}
$('download').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(D,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='peg-triage-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});
</script></body></html>""".replace("__REPORT_DATA__", payload)
